diagnostic.source:
// Diagnostic-only forwarding interposers; absent from timed executables.
#include <cstdio>
#include <cstdlib>
#include <dlfcn.h>
#include <sys/event.h>
#include <sys/socket.h>
#include <cerrno>
namespace {
thread_local bool server_thread = false;
struct Counts {
    unsigned long long waits=0, ready=0, reads=0, writes=0, full_batches=0;
    unsigned long long changes=0, send_calls=0, send_ok=0, send_block=0, recv_calls=0;
    unsigned long long nonempty_batches=0;
    // Emit after main has joined the only server thread.
    ~Counts() {
        std::fprintf(stderr,"C64_DIAGNOSTIC {\"waits\":%llu,\"ready\":%llu,\"read_events\":%llu,\"write_events\":%llu,\"full_batches\":%llu,\"changes\":%llu,\"send_calls\":%llu,\"send_ok\":%llu,\"send_block\":%llu,\"recv_calls\":%llu,\"nonempty_batches\":%llu}\n",waits,ready,reads,writes,full_batches,changes,send_calls,send_ok,send_block,recv_calls,nonempty_batches);
    }
} counts;
// Resolve native functions; every syscall still runs with its original arguments.
template<class T> T original(const char* name) {
    auto p=::dlsym(RTLD_NEXT,name);
    if(!p)std::abort();
    return reinterpret_cast<T>(p);
}
}
// Ke I/O belongs only to the production server thread in this benchmark.
extern "C" int kevent(int q,const struct kevent* c,int nc,struct kevent* e,int n,const timespec* t) {
    static const auto real=original<decltype(&::kevent)>("kevent");
    server_thread=true;
    const int result=real(q,c,nc,e,n,t);
    const int saved=errno;
    ++counts.waits;counts.changes+=nc;
    if(result>0){
        ++counts.nonempty_batches;counts.ready+=result;
        if(result==n)++counts.full_batches;
        for(int i=0;i<result;++i){
            if(e[i].filter==EVFILT_READ)++counts.reads;
            if(e[i].filter==EVFILT_WRITE)++counts.writes;
        }
    }
    errno=saved;return result;
}
// Count server sends only, including unsuccessful attempts.
extern "C" ssize_t send(int fd,const void* b,size_t n,int f) {
    static const auto real=original<decltype(&::send)>("send");
    const auto result=real(fd,b,n,f);const int saved=errno;
    if(server_thread){++counts.send_calls;if(result>0)++counts.send_ok;else if(result<0&&(saved==EAGAIN||saved==EWOULDBLOCK))++counts.send_block;}
    errno=saved;return result;
}
// Count native server receive calls without changing buffering or dispatch.
extern "C" ssize_t recv(int fd,void* b,size_t n,int f) {
    static const auto real=original<decltype(&::recv)>("recv");
    const auto result=real(fd,b,n,f);const int saved=errno;
    if(server_thread)++counts.recv_calls;
    errno=saved;return result;
}
